const host = $json.headers['x-forwarded-host'] || $json.headers.host;
const destino = 'https://' + host + '/webhook/radiografia-informe';
const html = `<!doctype html><html lang="es"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Radiografia de un proceso</title><style>
*{box-sizing:border-box} body{margin:0;background:#f4f6f7;font-family:-apple-system,Segoe UI,Roboto,Arial,sans-serif;color:#16191c}
.w{max-width:640px;margin:0 auto;padding:32px 20px 60px}
.k{font-size:11px;letter-spacing:2.4px;text-transform:uppercase;color:#0B4F6C;font-weight:700}
h1{font-size:30px;line-height:1.15;margin:10px 0 6px;letter-spacing:-.5px}
.sub{color:#5a656b;font-size:15px;line-height:1.5;margin:0 0 24px}
form{background:#fff;border-top:5px solid #0B4F6C;padding:22px;box-shadow:0 1px 3px rgba(0,0,0,.08)}
label{display:block;font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:.8px;color:#0B4F6C;margin:16px 0 6px}
input,textarea,select{width:100%;padding:11px 12px;border:1px solid #cfd8dc;font-size:15px;font-family:inherit;background:#fff}
textarea{min-height:110px;resize:vertical}
button{margin-top:22px;width:100%;padding:15px;background:#0B4F6C;color:#fff;border:0;font-size:16px;font-weight:700;cursor:pointer;letter-spacing:.3px}
button:disabled{opacity:.6}
.n{font-size:12px;color:#8b949a;margin-top:14px;line-height:1.5}
</style></head><body><div class="w">
<span class="k">Gerencia de Sistemas 2026</span>
<h1>Radiografia de un proceso</h1>
<p class="sub">Describa una tarea repetitiva de su organizacion. En unos segundos va a recibir un
informe con el veredicto, la arquitectura sugerida, los riesgos y el primer paso concreto.</p>
<form id="f">
<label>Que proceso es</label>
<textarea name="proceso" required placeholder="Ej.: cada vez que llega una factura por correo, una persona la abre, copia los datos a una planilla y avisa al area de pagos."></textarea>
<label>Quien lo hace hoy</label>
<input name="quien" required placeholder="Ej.: una administrativa del area de compras">
<label>Cuantas veces por semana ocurre</label>
<input name="veces" type="number" min="1" value="20" required>
<label>Cuantos minutos lleva cada vez</label>
<input name="minutos" type="number" min="1" value="8" required>
<label>Que pasa si sale mal</label>
<select name="criticidad">
<option>Se corrige sin consecuencias</option>
<option>Genera retrabajo y demoras</option>
<option>Impacta a un cliente o a un pago</option>
<option>Tiene consecuencia legal o economica seria</option>
</select>
<button id="b" type="submit">Analizar el proceso</button>
<p class="n">El analisis lo hace un modelo de IA con los criterios del curso. No se guarda ningun dato.</p>
</form></div>
<script>
document.getElementById('f').addEventListener('submit', async (e) => {
  e.preventDefault();
  const b = document.getElementById('b');
  b.disabled = true; b.textContent = 'Analizando…';
  const d = Object.fromEntries(new FormData(e.target).entries());
  const r = await fetch('DESTINO', {method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify(d)});
  document.open(); document.write(await r.text()); document.close();
});
</script></body></html>`;
return [{ json: { html: html.replace('DESTINO', destino) } }];

const b = $('Recibir el proceso').first().json.body;
let ia = {};
try {
  const bruto = ($json.text || $json.response || JSON.stringify($json)).trim();
  ia = JSON.parse(bruto.replace(/^```(json)?/i,'').replace(/```$/,'').trim());
} catch (e) { ia = { veredicto:'MEDIO', razon:'No se pudo interpretar la respuesta del modelo.',
  arquitectura:[], riesgos:[], primer_paso:'Reintentar el analisis.' }; }

// Las horas salen de lo que declaro el gerente, no de una cifra inventada.
const hs_sem = (Number(b.veces) * Number(b.minutos)) / 60;
const hs_ano = Math.round(hs_sem * 48);
const col = { ALTO:'#1b7a4b', MEDIO:'#b06a1a', BAJO:'#8b949a' }[String(ia.veredicto).toUpperCase()] || '#0B4F6C';
const li = (a) => (a||[]).map(x => `<li>${x}</li>`).join('');
const pasos = (ia.arquitectura||[]).map((x,i) => `<div class="p"><span>${i+1}</span>${x}</div>`).join('<div class="fl">&rarr;</div>');

const html = `<!doctype html><html lang="es"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1"><title>Radiografia del proceso</title><style>
*{box-sizing:border-box} body{margin:0;background:#f4f6f7;font-family:-apple-system,Segoe UI,Roboto,Arial,sans-serif;color:#16191c}
.w{max-width:720px;margin:0 auto;padding:30px 20px 60px}
.c{background:#fff;border-top:5px solid #0B4F6C;padding:26px;box-shadow:0 1px 3px rgba(0,0,0,.08)}
.k{font-size:11px;letter-spacing:2.4px;text-transform:uppercase;color:#0B4F6C;font-weight:700}
h1{font-size:26px;margin:8px 0 18px;letter-spacing:-.4px}
.vd{display:inline-block;background:${col};color:#fff;padding:7px 16px;font-weight:700;letter-spacing:1.5px;font-size:13px}
.rz{font-size:16px;line-height:1.55;margin:14px 0 22px}
h2{font-size:12px;text-transform:uppercase;letter-spacing:1.2px;color:#0B4F6C;border-bottom:1px solid #dde4e7;padding-bottom:6px;margin:26px 0 12px}
.rpr div{padding:9px 0;border-bottom:1px solid #eef2f4;font-size:15px;line-height:1.5}
.rpr b{display:inline-block;width:92px;color:#0B4F6C;font-size:12px;text-transform:uppercase;letter-spacing:.8px;vertical-align:top}
.rpr span{display:inline-block;width:calc(100% - 100px)}
.arq{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin:6px 0}
.p{background:#EAF1F5;border-left:3px solid #0B4F6C;padding:9px 12px;font-size:13.5px;font-weight:600;flex:1 1 150px}
.p span{display:inline-block;background:#0B4F6C;color:#fff;width:18px;height:18px;line-height:18px;text-align:center;font-size:11px;margin-right:7px}
.fl{color:#8b949a}
ul{margin:0;padding-left:20px} li{font-size:14.5px;line-height:1.55;margin-bottom:7px}
.num{display:flex;gap:14px;margin:8px 0 4px}
.num div{flex:1;border:1px solid #dde4e7;border-top:3px solid #0B4F6C;padding:14px}
.num b{display:block;font-size:30px;letter-spacing:-1px;color:#0B4F6C}
.num small{color:#5a656b;font-size:12.5px;line-height:1.4;display:block;margin-top:3px}
.ps{background:#16191c;color:#fff;padding:18px 20px;margin-top:24px;font-size:15.5px;line-height:1.5}
.ps b{display:block;font-size:11px;letter-spacing:1.6px;color:#8fb6c8;text-transform:uppercase;margin-bottom:6px}
.pie{font-size:11.5px;color:#8b949a;margin-top:18px;line-height:1.5}
</style></head><body><div class="w"><div class="c">
<span class="k">Gerencia de Sistemas 2026 &middot; analisis automatico</span>
<h1>Radiografia del proceso</h1>
<span class="vd">APTITUD ${String(ia.veredicto).toUpperCase()}</span>
<p class="rz">${ia.razon||''}</p>
<h2>El patron: recibir, procesar, responder</h2>
<div class="rpr">
 <div><b>Recibir</b><span>${ia.recibir||''}</span></div>
 <div><b>Procesar</b><span>${ia.procesar||''}</span></div>
 <div><b>Responder</b><span>${ia.responder||''}</span></div>
</div>
<h2>Lo que hoy cuesta, con sus propios numeros</h2>
<div class="num">
 <div><b>${hs_sem.toFixed(1)} h</b><small>por semana, dedicadas a esta tarea<br>(${b.veces} veces x ${b.minutos} min)</small></div>
 <div><b>${hs_ano} h</b><small>por ano, sobre 48 semanas habiles</small></div>
</div>
<h2>Arquitectura sugerida</h2>
<div class="arq">${pasos}</div>
<p style="font-size:14px;line-height:1.55;margin-top:10px"><b>Donde entra la IA:</b> ${ia.ia||''}</p>
<h2>Riesgos y controles</h2><ul>${li(ia.riesgos)}</ul>
<div class="ps"><b>Primer paso</b>${ia.primer_paso||''}</div>
<p class="pie">Analisis generado por un flujo de automatizacion con IA, a partir de la descripcion
ingresada. Las horas se calculan con los valores declarados por usted; no son una estimacion del sistema.
Documento de trabajo para uso didactico.</p>
</div></div></body></html>`;
return [{ json: { html } }];
